def run(document, schema, options \\ []) do
  pipeline = Absinthe.Pipeline.for_document(schema, options)
  input = %Absinthe.Blueprint{schema: schema, document: document}

  case Absinthe.Pipeline.run(input, pipeline) do
    {:ok, %Absinthe.Blueprint{execution_result: result}} ->
      {:ok, result}

    {:error, %Absinthe.Blueprint{errors: errors}} ->
      {:error, Enum.map(errors, &to_string/1)}
  end
end

